cd /work && python3 - <<'EOF'
import json, subprocess, sys, time
L=40
nid = L
layers=[]
for _ in range(13):
    layers.append([nid,nid+1]); nid+=2
dest=nid; n=nid+1
edges=[]
def add(u,v,lab): edges.append({"u":u,"v":v,"ping_us":1,"ack_us":1,"label":lab})
for i in range(L-1): add(i,i+1,"c%d"%(i%10))
for v in layers[0]: add(L-1,v,"L0")
for i in range(12):
    for u in layers[i]:
        for v in layers[i+1]: add(u,v,"M%d"%(i%10))
for u in layers[-1]: add(u,dest,"z")
print("n",n,"edges",len(edges))
rounds=[{"launch_us":0,"timeout_us":1000000,"host_delay_us":1,"drop_host_ack":False,"drop_ping":[],"drop_ack":[]} for _ in range(48)]
doc={"version":1,"n":n,"capacity":[48]*n,"edges":edges,"rounds":rounds}
raw=json.dumps(doc).encode()
t=time.time()
p=subprocess.run([sys.executable,"-I","/work/submission/main.py"],input=raw,capture_output=True)
el=time.time()-t
print("rc",p.returncode,"time %.2fs"%el,"outbytes",len(p.stdout))
if p.returncode==0:
    o=json.loads(p.stdout)
    print("paths",o["summary"]["topology_paths"],"classes",o["summary"]["observable_classes"],
          "siglen",len(o["classes"][0]["signature"]), "witness len", len(o["classes"][0]["candidate_witnesses"][0]))
EOF
